    p = float(MODEL.predict_proba(pd.DataFrame([customer.model_dump()]))[:, 1][0])
    return Prediction(churn_probability=p,
                      decision='contact' if p >= THRESHOLD else 'hold',
                      model_sha=MODEL_SHA, threshold=THRESHOLD, latency_ms=...)
